import React, { useState, useEffect } from "react";
import { ethers } from "ethers";
import LandRegistryABI from "./contracts/LandRegistry.json";
import LoanBankABI from "./contracts/LoanBank.json";

const landRegistryAddress = "0xeB4770294ccC6dBdaAFe6905c08C91D56B6d53B1";
const loanBankAddress = "0x2D7886b78275600A69cE61Bf9DADC46D15bc3367";

function App() {
  const [account, setAccount] = useState(null);
  const [provider, setProvider] = useState(null);
  const [signer, setSigner] = useState(null);
  const [landRegistry, setLandRegistry] = useState(null);
  const [loanBank, setLoanBank] = useState(null);

  useEffect(() => {
    async function loadBlockchainData() {
      if (window.ethereum) {
        const provider = new ethers.providers.Web3Provider(window.ethereum);
        await window.ethereum.request({ method: "eth_requestAccounts" });
        const signer = provider.getSigner();
        const account = await signer.getAddress();
        setAccount(account);
        setProvider(provider);
        setSigner(signer);

        const landRegistryContract = new ethers.Contract(
          landRegistryAddress,
          LandRegistryABI,
          signer
        );

        const loanBankContract = new ethers.Contract(
          loanBankAddress,
          LoanBankABI,
          signer
        );

        setLandRegistry(landRegistryContract);
        setLoanBank(loanBankContract);
      } else {
        alert("Please install MetaMask!");
      }
    }
    loadBlockchainData();
  }, []);

  async function registerLand(plotId, metadata) {
    try {
      const tx = await landRegistry.registerLand(plotId, metadata, account);
      await tx.wait();
      alert("Land registered successfully!");
    } catch (error) {
      console.error(error);
      alert("Land registration failed.");
    }
  }

  async function applyForLoan(principal, interestRate) {
    try {
      const tx = await loanBank.createLoan(principal, interestRate);
      await tx.wait();
      alert("Loan applied successfully!");
    } catch (error) {
      console.error(error);
      alert("Loan application failed.");
    }
  }

  async function purchaseLand(plotId) {
    try {
      const tx = await landRegistry.purchaseLand(plotId);
      await tx.wait();
      alert("Land purchased successfully!");
    } catch (error) {
      console.error(error);
      alert("Land purchase failed.");
    }
  }

  async function repayLoan(amount) {
    try {
      const tx = await loanBank.repayLoan(amount);
      await tx.wait();
      alert("Loan repaid successfully!");
    } catch (error) {
      console.error(error);
      alert("Loan repayment failed.");
    }
  }

  async function checkDefault() {
    try {
      const tx = await loanBank.checkDefault(account);
      await tx.wait();
      alert("Default check completed!");
    } catch (error) {
      console.error(error);
      alert("Default check failed.");
    }
  }

  return (
    <div>
      <h1>Land & Loan Management</h1>
      <p>Connected Account: {account}</p>

      <button onClick={() => registerLand("plot123", "metadata_here")}>Register Land</button>
      <button onClick={() => applyForLoan(1000, 5)}>Apply for Loan</button>
      <button onClick={() => purchaseLand("plot123")}>Purchase Land</button>
      <button onClick={() => repayLoan(500)}>Repay Loan</button>
      <button onClick={checkDefault}>Check Default</button>
    </div>
  );
}

export default App;
